248	    /**
249	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
250	     * already reached this many owners is rejected as a conflict.
251	     */
252	    static final int MAX_OWNERS_PER_CITY = 50;
253	
254	    /**
255	     * Number of owners that must already exist in a city before a new owner registered there is
256	     * flagged with a capacity warning. Once the count already recorded for the city reaches this
257	     * value (but is still below {@link #MAX_OWNERS_PER_CITY}), the new owner carries
258	     * {@code capacityWarning == true} to signal that the city is approaching its capacity limit.
259	     */
260	    static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
261	
262	    /**
263	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
264	     * already reached this many registrations is rejected as a rate-limit violation.
265	     */
266	    static final int MAX_OWNERS_PER_DAY = 100;
267	
268	    /**
269	     * Number of owners that must already have registered on a day before a new registration is
270	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
271	     * value, the new owner carries {@code bulkSignupWarning == true}.
272	     */
273	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
274	
275	    @Override
276	    @Transactional
277	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
278	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
279	            throw new DisposableEmailDomainException(owner.getEmail());
280	        }
281	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
282	        rejectIdentityCollision(owner);
283	        List<Owner> householdMembers = findHouseholdMembers(owner);
284	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
285	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
286	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
287	        }
288	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
289	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
290	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
291	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
292	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
293	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
294	        }
295	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
296	        flagPossibleDuplicate(owner, sharesHousehold);
297	        owner.setNamesakeCount(countNamesakes(owner));
298	        owner.setHouseholdSize(householdMembers.size() + 1);
299	        owner.setMembershipLevel(OwnerMembership.cappedLevel(owner, householdMembers));
300	        owner.setCustomerCode(assignCustomerCode(owner));
301	        ownerRepository.save(owner);
302	        ownerAuditLogger.ownerCreated(owner);
303	        return owner.getHouseholdId();
304	    }
305	
306	    /**
307	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
308	     * another active owner. Because the telephone is part of the key, only an existing owner sharing
309	     * every key component (normalized telephone, lower-cased email and the last name's Soundex code)
310	     * is a hard duplicate; telephone equality remains a prerequisite, so it prefilters the candidates.
311	     */
312	    private void rejectIdentityCollision(Owner owner) {
313	        String identityKey = OwnerIdentityKey.of(owner);
314	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
315	            .filter(ClinicServiceImpl::isActive)
316	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
317	        if (collides) {
318	            throw new DuplicateOwnerException(identityKey);
319	        }
320	    }
321	
322	    /**
323	     * Whether an existing owner is still active, i.e. has not been soft-deleted. Soft-deleted owners
324	     * are retained for history but ignored by the create-time duplicate and identity checks.
325	     */
326	    private static boolean isActive(Owner owner) {
327	        return !Boolean.TRUE.equals(owner.getDeleted());
328	    }
329	
330	    /**
331	     * Build the new owner's {@code customerCode} and de-duplicate it against existing owners. The
332	     * base code is derived from the owner's locality, telephone and last name; if it already belongs
333	     * to another owner it is suffixed with the smallest {@code "-<n>"} (n &gt;= 2) that is still free.
334	     */
335	    private String assignCustomerCode(Owner owner) {
336	        String baseCode = CustomerCodeGenerator.format(
337	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
338	            owner.getTelephone(), owner.getLastName());
339	        Set<String> takenCodes = ownerRepository.findByCustomerCodeStartingWith(baseCode).stream()
340	            .map(Owner::getCustomerCode)
341	            .collect(Collectors.toSet());
342	        return CustomerCodeGenerator.deduplicate(baseCode, takenCodes::contains);
343	    }
344	
345	    /**
346	     * Flag the new owner as a possible (soft) duplicate of an existing owner whose identity key
347	     * <em>differs</em> but whose last name shares the same Soundex code and whose postcode is equal.
348	     * The new owner is still created; {@code possibleDuplicate} is set to whether such a match exists
349	     * and {@code possibleDuplicateOf} to the matching owner's id (the lowest when several match), or
350	     * {@code null} when there is no match.
351	     *
352	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
353	     * member rather than a suspected duplicate, so it is never flagged.
354	     */
355	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
356	        Owner match = sharesHousehold ? null : findSoftMatchCandidates(owner).stream()
357	            .min(Comparator.comparingInt(Owner::getId))
358	            .orElse(null);
359	        owner.setPossibleDuplicate(match != null);
360	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
361	    }
362	
363	    /**
364	     * Find the existing active owners that are a soft match for the new owner: those sharing its
365	     * postcode and its last name's {@link org.springframework.samples.petclinic.util.Soundex Soundex}
366	     * code, but deriving a <em>different</em> {@link OwnerIdentityKey identity key} (an equal key is a
367	     * hard duplicate, rejected earlier). An owner without a postcode has no soft-match candidates.
368	     */
369	    private List<Owner> findSoftMatchCandidates(Owner owner) {
370	        if (owner.getPostcode() == null) {
371	            return List.of();
372	        }
373	        String soundex = Soundex.encode(owner.getLastName());
374	        String identityKey = OwnerIdentityKey.of(owner);
375	        return ownerRepository.findByPostcode(owner.getPostcode()).stream()
376	            .filter(ClinicServiceImpl::isActive)
377	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
378	            .filter(existing -> !identityKey.equals(OwnerIdentityKey.of(existing)))
379	            .toList();
380	    }
381	
382	    @Override
383	    @Transactional
384	    public void saveOwner(Owner owner) throws DataAccessException {
385	        ownerRepository.save(owner);
386	    }
387	
388	    /**
389	     * Count the owners that already exist sharing this owner's first name and last name, compared
390	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
391	     */
392	    private int countNamesakes(Owner owner) {
393	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
394	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
395	            .count();
396	    }
397	
398	    /**
399	     * Find the existing owners that already share this owner's household, i.e. that derive the same
400	     * computed {@code householdId} (the same last name and postcode). An owner without a postcode
401	     * has no household peers.
402	     */
403	    private List<Owner> findHouseholdMembers(Owner owner) {
404	        if (owner.getPostcode() == null) {
405	            return List.of();
406	        }
407	        String householdId = owner.getHouseholdId();
408	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
409	            .filter(ClinicServiceImpl::isActive)
410	            .filter(existing -> householdId.equals(
411	                HouseholdIdGenerator.generate(existing.getLastName(), existing.getPostcode())))
412	            .toList();
413	    }
414	
415	    @Override
416	    @Transactional(readOnly = true)
417	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
418	        return ownerRepository.findByLastName(lastName);
419	    }
420	
421	    @Override
422	    @Transactional(readOnly = true)
423	    public Collection<Visit> findVisitsByPetId(int petId) {
424	        return visitRepository.findByPetId(petId);
425	    }
426	
